+class JvmtiInvokeOnAttachContext {
+ private:
+  void* const _entry_point;
+ public:
+  JvmtiInvokeOnAttachContext(void* entry_point) : _entry_point(entry_point) {}
+  jint operator()(JvmtiAgent* agent) {
+    return invoke_startup(agent, _entry_point);
+  }
+};
