+#ifdef ASSERT
+static void assert_loaded(const JvmtiAgent* agent) {
+  assert(agent != nullptr, "invariant");
+  assert(agent->path() == nullptr, "invariant");
+  assert(agent->resolver() != nullptr, "invariant");
+  assert(!agent->is_associated(), "invariant");
+}
+#endif
